L000057	\title{Exact Floquet dynamics of strongly damped driven quantum systems}
L000058	
L000059	\author{Konrad Mickiewicz}
L000060	\affiliation{Institut f{\"u}r Theoretische Physik, Technische Universit{\"a}t Dresden,
