L000203	\subsection{Influence functional formalism}
L000204	
L000205	We provide details on the influence functional  formulation of open system dynamics \cite{keeling2025Process}. We define the quantum channel that propagates a general state of system and environment from time $t_{n-1}$ to $t_{n}$ via
L000206	\begin{equation}\label{eq:channel}
L000207	    \mathcal{U}_n\rho=U(t_{n},t_{n-1})\rho U^\dagger(t_{n},t_{n-1})
L000208	\end{equation}
L000209	where $U(t_f,t_i)$ are the standard unitary operators generated by $H(t)$. Formally, one can define the influence functional $\mathcal{I}$ as the multi-linear map from a set of local superoperators $\{\mathcal{O}_n\}$ and the system initial state $\rho_\mathrm{sys}$ to the corresponding multi-time correlation function \eqref{eq:cf}
L000210	\begin{equation}
L000211	    \mathcal{I}[\{\mathcal{O}_n\},\rho_\mathrm{sys}]=\braket{\mathcal{O}_N(N\delta t)\ldots \mathcal{O}_2(2\delta t) \mathcal{O}_1(\delta t)}.
L000212	\end{equation}
L000213	In order to obtain lower-order multi-time observables, one chooses $\mathcal{O}_m=\id$ for a subset of superoperators. For instance, time-local observables as encoded in the reduced system state $\rho_\mathrm{sys}(t)$ can be obtained from setting all but one operator to the identity.
L000214	\begin{equation}
L000215	    \tr_\mathrm{sys} \mathcal{O}_n\rho_\mathrm{sys}(n\delta t)=\mathcal{I}[\id,\ldots ,\id,\mathcal{O}_n,\id\ldots,\id;\rho_\mathrm{sys} ].
L000216	\end{equation}
L000217	We use throughout the superoperator formulation of quantum dynamics, where operators are mapped to vectors. Specifically, we choose a basis for the system Hilbert space such that local operators (e.g.~the reduced density matrix) are vectorized $\rho_\mathrm{sys}^\mu=\braket{\mu^+|\rho_\mathrm{sys}|\mu^-}$, with $\mu\equiv(\mu^+,\mu^-)$ taking values from $1,\ldots ,\mathrm{dim}(\mathcal{H}_\mathrm{sys})^2$.
L000218	Choosing operators $\mathcal{O}_n$ to be individual basis elements, i.e.~$\mathcal{O}_n\rho_\mathrm{sys}:=\ketbra{(\mu_n')^{+} }{\mu_{n-1}^{+}}\rho_\mathrm{sys}\ketbra{\mu_{n-1}^{-} }{(\mu_n')^{-}}$, leads to the tensor representation \eqref{eq:if_def}. The path-conditioned operators $\mathcal{U}_n^{\mu\nu}$ are superoperators in the environment Hilbert space and are given explicitly as
L000219	\begin{equation}
L000220	    \begin{split}
L000221	&\mathcal{U}^{\mu_n\mu_n'}_n\rho_\mathrm{env}=\\&\braket{\mu_n^+|U(t_{n},t_{n-1})|(\mu_n')^+}\rho_\mathrm{env}\braket{(\mu_n')^-|U^\dagger(t_{n},t_{n-1})|\mu^-_n}
L000222	\end{split}
L000223	\end{equation}
L000224	according to Eq.~\eqref{eq:channel}.
L000225	
L000226	\subsection{Heat current density}
L000227	
L000228	For bosonic environments, the heat current density at time $t$ is given as \cite{Gribben2022Oct, albarelli2024Pseudomode}
L000229	\begin{equation}\label{eq:heat_current}
L000230	\begin{split}
L000231	    j(t, \omega) = 2J(\omega)\omega \int_{0}^t ds& \mathrm{Im} \{ ((1+2n_B(\omega))\sin(\omega (t-s))\\
L000232	                   & + \ii \cos(\omega (t-s))) \langle S(t)S(s)\rangle\}.
L000233	\end{split}
L000234	\end{equation}
L000235	On order to remove the dependence on the final time $t$ we consider the period-averaged heat current \eqref{eq:av_heat_current}. At asymptotic times $t\rightarrow\infty$.
L000236	one obtains the following expression for the average heat current
L000237	\begin{equation}\label{eq:av_heat_current_expl}
L000238	\begin{split}
L000239	    \overline{j}(\omega)={2J(\omega)\omega} \int_0^\infty d\tau \mathrm{Im} \{ (&(1+2n_B(\omega))\sin(\omega \tau) \\
L000240	    +& i \cos(\omega \tau)) \overline{C}(\tau)\}.
L000241	\end{split}
L000242	\end{equation}
L000243	where the period-averaged asymptotic correlation function is
L000244	\begin{equation}
L000245	    \overline{C}(\tau)  =\frac{1}{T} \int_{t}^{t+T} dt'\langle S(t'+\tau)S(t')\rangle.
L000246	\end{equation}
L000247	The primary computational challenge lies in the evaluation of this correlation function in the Floquet steady state, which can be achieved efficiently with the methods introduced in the main text.
L000248	
L000249	For systems with a finite memory time the correlation function will factorize for large $\tau$
L000250	\begin{equation}
L000251	     \langle S(t+\tau)S(t)\rangle \rightarrow \langle S(t+\tau)\rangle \langle S(t)\rangle.
L000252	\end{equation}
L000253	Note that the expression on the right hand side may or may not be zero, depending on the details of the model. In order to determine the integral in Eq.~\eqref{eq:av_heat_current_expl} we split the correlation function into a connected and factorized term
L000254	\begin{equation}
L000255	    \overline{C}(\tau) = \overline{C}_\mathrm{decay}(\tau) + \overline{C}_\mathrm{asym}(\tau),
L000256	\end{equation}
L000257	where
L000258	\begin{equation}
L000259	    \overline{C}_\mathrm{asym}(\tau)=\frac{1}{T}\int_t^{t+T}\diff t' \langle S(t+\tau)\rangle \langle S(t)\rangle.
L000260	\end{equation}
L000261	The connected correlation function $\overline{C}_\mathrm{decay}$ decays for large $\tau$, allowing for a direct numerical integration. The remaining term $\overline C_\mathrm{asym}$ is $T$-periodic and can therefore be expanded as a Fourier series. In fact, since $\braket{S(t)}$ is periodic and real the expansion takes the form
L000262	\begin{equation} \label{fourier}
L000263	    \overline C_{\mathrm{asym}}(\tau) = \sum_{n=0}^\infty c_n\cos(n \omega_d \tau),
L000264	\end{equation}
L000265	with positive, real coefficients $c_n$.
L000266	Inserting this in Eq.~\eqref{eq:av_heat_current_expl} one finds delta-peak contributions to the heat current density
L000267	\begin{equation} \label{asym_hc}
L000268	\overline{j}_{\mathrm{asym}}(\omega) = \pi J(\omega)\omega \sum_{n=0}^\infty c_n  \delta(\omega - \omega_dn).
L000269	\end{equation}
L000270	
L000271	\subsection{Total energy transfer}
L000272	The total amount of heat transferred from the system to the bath is given by the total heat current
L000273	\begin{equation}\label{eq:curr_tot}
L000274	    \overline{I}= \int_0^\infty d\omega \;\overline{j}(\omega).
L000275	\end{equation}
L000276	In Fig. \ref{fig:total_hc} we display the total heat current as a function of the driving frequency. While at low driving frequencies, resonances with the system transitions lead to a non-monotonic behavior, the heat current follows a smooth asymptotic towards zero as the driving frequency is increased. At large frequencies the driving no longer influences the dynamics due to the large detuning from all resonances. Then the system is described by the undriven equilibrium state with vanishing currents. However, in the case of longitudinal driving, the heat current vanishes significantly slower compared to transversal driving.
